#!/usr/bin/env php
<?php

require_once __DIR__ . '/../vendor/autoload.php';

use Dsl\App\MemberShip;
use Dsl\App\Page;

// Konfiguration laden wie in public/index.php
$config = [];
$configLocal = [];

require_once __DIR__ . '/../config/web.config.php';
if (file_exists(__DIR__ . '/../config/web.config.local.php')) {
    require_once __DIR__ . '/../config/web.config.local.php';
}

Page::$config = array_replace_recursive($config, $configLocal);

function setupDocuData() {
    echo "Bereite Datenbank für Dokumentation vor...\n";

    $db = Page::db();

    // 0. Infrastruktur-Bereinigung (immer durchführen für Dienststelle 99, 9901)
    // Damit die Tests (besonders 01-infrastruktur_setup.cy.js) die Struktur neu anlegen können.
    echo "Führe radikale Bereinigung der Test-Infrastruktur durch (Ressort 99, FB 9901, User r2/r3)...\n";
    $db->query("DELETE FROM user WHERE user_name IN ('r2_user', 'r3_user')");
    $db->query("DELETE FROM user WHERE fk_dienststelle IN ('99', '9901') AND user_name NOT IN ('r1_user')");
    $db->query("DELETE FROM massnahme WHERE fk_dienststelle IN ('99', '9901')");
    $db->query("DELETE FROM fachplanung WHERE fk_dienststelle IN ('99', '9901')");
    $db->query("DELETE FROM dienststelle WHERE nummer = '9901'");
    $db->query("DELETE FROM dienststelle WHERE nummer = '99'");

    // R1 ist der Systemadmin und immer vorhanden/erforderlich als Startpunkt
    $u = ['r1_user', 'Admin', 'R1', 'r1@example.com', 'r1_password', 8, null];

    echo "Erstelle/Update Basis-Admin {$u[0]}... ";
    $stmt = $db->prepare("SELECT user_name FROM user WHERE user_name = ?");
    $stmt->execute([$u[0]]);
    $exists = $stmt->fetch();

    if ($exists) {
        $password = MemberShip::encryptPassword($u[4]);
        $stmt     = $db->prepare("UPDATE user SET last_name = ?, first_name = ?, email = ?, password = ?, access_level = ?, fk_dienststelle = ?, ldap = ? WHERE user_name = ?");
        $stmt->execute([$u[1], $u[2], $u[3], $password, $u[5], $u[6], 0, $u[0]]);
        echo "UPDATED\n";
    } else {
        $result = MemberShip::createUser($u[0], $u[1], $u[2], $u[3], $u[4], $u[5], $u[6], false);
        echo "$result\n";
    }

    // Wenn NICHT die gesamte Kette läuft (z.B. nur Einzeltest für Änderungsanträge),
    // müssen r2/r3 und die Dienststellen trotzdem da sein.
    // Wir prüfen, ob ein spezifischer Test-Parameter übergeben wurde, der NICHT der Infra-Test ist.
    $argv_string = isset($GLOBALS['argv']) ? implode(' ', $GLOBALS['argv']) : '';
    $is_partial_run = (strpos($argv_string, 'cypress/e2e/') !== false && strpos($argv_string, '01-infrastruktur_setup.cy.js') === false);

    if ($is_partial_run) {
        echo "Partial-Run erkannt: Erstelle benötigte Infrastruktur vorab per DB...\n";
        $db->query("INSERT IGNORE INTO dienststelle (nummer, name, bemerkung, fk_ressort, aktiv) VALUES ('99', '99 Dokumentations-Ressort', '', NULL, 1)");
        $db->query("INSERT IGNORE INTO dienststelle (nummer, name, bemerkung, fk_ressort, aktiv) VALUES ('9901', '9901 Dokumentations-Fachbereich', '', '99', 1)");

        $extra_users = [
            ['r2_user', 'Redakteur', 'R2', 'r2@example.com', 'r2_password', 4, '99'],
            ['r3_user', 'Redakteur', 'R3', 'r3@example.com', 'r3_password', 2, '9901'],
        ];
        foreach ($extra_users as $u) {
            $password = MemberShip::encryptPassword($u[4]);
            $stmt = $db->prepare("SELECT user_name FROM user WHERE user_name = ?");
            $stmt->execute([$u[0]]);
            if (!$stmt->fetch()) {
                MemberShip::createUser($u[0], $u[1], $u[2], $u[3], $u[4], $u[5], $u[6], false);
                echo "User {$u[0]} angelegt.\n";
            }
        }
    }

    // Testdaten für Änderungsanträge vorbereiten (2026)
    echo "Erstelle Testdaten für Änderungsanträge (2026)...\n";
